  context.set('seq', seq);

  node.status({ fill: 'blue', shape: 'dot', text: 'DBIRTH ' + new Date().toLocaleTimeString() });
  return { topic: 'spBv1.0/' + GROUP + '/DBIRTH/' + GATEWAY_ID + '/' + DEVICE_ID, payload: birth };
}

