// Answer a Sparkplug B rebirth request.
//
// THE NCMD LISTENER HAS ALWAYS BEEN WIRED TO THIS NODE AND THIS NODE HAS NEVER EXISTED. The flow
// subscribed to spBv1.0/+/NCMD/+ and routed every request into a dangling wire, so the ingestion
// daemon's rebirth requests -- at startup, on every sequence gap, and now on every broker capture
// -- were received by the simulator and discarded. The only way to get a birth out of this fleet
// was to nudge a node and redeploy.
//
// WHAT A REBIRTH IS: "say who you are again". It restates the node's birth certificate, which is
// where the metric alias table lives. It is not a command that changes anything on the plant, and
// it is the ONLY NCMD this stack's ACL permits the daemon to publish.
//
// FOUR OUTPUTS, ONE PER GATEWAY, because each mqtt-out node holds a different broker connection:
// mosquitto.acl pins the topic's edge-node segment to the account that publishes it, so a gateway's
// NBIRTH can only leave through that gateway's own connection.
//
// NBIRTH ONLY, NOT DBIRTH. The node-level birth is what carries the alias table and what
// captures.manifest.birth_captured keys on. Device births stay on their own BIRTH_EVERY_SCANS
// cycle in the device simulation nodes, whose per-instance context this node cannot reach.
// ---------------------------------------------------------------------------------------------
const GATEWAYS = [
  { id: 'gwy120000000000400080000', name: 'Sim_Gateway_Cell1_Machining' },  // output 1
  { id: 'gwy130000000000400080000', name: 'Sim_Gateway_Cell2_Robotics' },   // output 2
  { id: 'gwy140000000000400080000', name: 'Sim_Gateway_Cell3_OEE' },        // output 3
  { id: 'gwy150000000000400080000', name: 'Sim_Gateway_Site_BMS' },         // output 4
];
const GROUP = 'ACS-Cymru';

// spBv1.0/<group>/NCMD/<edge_node>. Anything else is not addressed to a node here.
const parts = String(msg.topic || '').split('/');
if (parts.length < 4 || parts[2] !== 'NCMD') { return null; }
const edgeNode = parts[3];

const index = GATEWAYS.findIndex(g => g.id === edgeNode);
if (index === -1) {
  node.status({ fill: 'grey', shape: 'ring', text: 'NCMD for ' + edgeNode + ' (not ours)' });
  return null;
}

// NOT INSPECTED FOR THE Node Control/Rebirth METRIC. The daemon publishes exactly one kind of NCMD
// -- its ACL permits nothing else -- and decoding protobuf here to confirm what we already know
// would add a failure mode (an undecodable payload) to a handler whose whole job is to be
// reliable. If this simulator ever receives a different NCMD, restating who it is remains a safe
// and correct answer.
const gw = GATEWAYS[index];

// A REBIRTH RESTARTS THE SEQUENCE. Sparkplug requires seq to begin at 0 on a birth, and the
// heartbeat node keeps its own counter -- so this sets the shared flow value both read, or the
// daemon would report a gap immediately after the birth it just asked for.
flow.set('seq_' + gw.id, 1);

const payload = {
  timestamp: Date.now(),
  seq: 0,
  metrics: [{ name: 'Gateway_Status', datatype: 12, string_value: 'ONLINE' }],
};

node.status({ fill: 'green', shape: 'dot', text: 'NBIRTH ' + gw.name + ' ' + new Date().toLocaleTimeString() });

const out = [null, null, null, null];
out[index] = { topic: 'spBv1.0/' + GROUP + '/NBIRTH/' + gw.id, payload: payload };
return out;
